13.64\"</td><td>44.11</td><td>611,941.6671</td><td>2,140,622.2149</td><td>-0°21\"11.875495\"</td><td>0.99975489</td><td>19°21\"23.495674\"N</td><td>97°56\"3.040185\"W</td></tr><tr><td>29-30</td><td>52°55\"37.23\"</td><td>32.63</td><td>611,973.4973</td><td>2,140,652.7527</td><td>-0°21\"12.256646\"</td><td>0.99975498</td><td>19°21\"24.482644\"N</td><td>97°56\"1.942843\"W</td></tr><tr><td>30-31</td><td>44°23\"33.99\"</td><td>87.92</td><td>611,999.5312</td><td>2,140,672.4227</td><td>-0°21\"12.564994\"</td><td>0.99975505</td><td>19°21\"25.117261\"N</td><td>97°56\"1.046448\"W</td></tr><tr><td>31-32</td><td>45°47\"32.51\"</td><td>42.09</td><td>612,061.0369</td><td>2,140,735.2461</td><td>-0°21\"13.303989\"</td><td>0.99975522</td><td>19°21\"27.148479\"N</td><td>97°55\"58.925227\"W</td></tr><tr><td>32-33</td><td>49°57\"7.65\"</td><td>30.81</td><td>612,091.2057</td><td>2,140,764.5918</td><td>-0°21\"13.665542\"</td><td>0.99975531</td><td>19°21\"28.096999\"N</td><td>97°55\"57.885066\"W</td></tr><tr><td>33-34</td><td>295°12\"48.11\"</td><td>619.71</td><td>612,114.7924</td><td>2,140,784.4170</td><td>-0°21\"13.946219\"</td><td>0.99975537</td><td>19°21\"28.737149\"N</td><td>97°55\"57.072499\"W</td></tr><tr><td>34-35</td><td>209°15\"45.73\"</td><td>21.53</td><td>611,554.1263</td><td>2,141,048.4062</td><td>-0°21\"7.745536\"</td><td>0.99975382</td><td>19°21\"37.436756\"N</td><td>97°56\"16.232228\"W</td></tr><tr><td>35-36</td><td>192°47\"0.17\"</td><td>17.19</td><td>611,543.6019</td><td>2,141,029.6233</td><td>-0°21\"7.613962\"</td><td>0.99975379</td><td>19°21\"36.827875\"N</td><td>97°56\"16.596886\"W</td></tr><tr><td>36-37</td><td>173°51\"9.76\"</td><td>82.79</td><td>611,539.7976</td><td>2,141,012.8561</td><td>-0°21\"7.560029\"</td><td>0.99975378</td><td>19°21\"36.283219\"N</td><td>97°56\"16.730801\"W</td></tr><tr><td>37-1</td><td>208°40\"29.99\"</td><td>59.08</td><td>611,548.6633</td><td>2,140,930.5407</td><td>-0°21\"7.608175\"</td><td>0.99975381</td><td>19°21\"33.603828\"N</td><td>97°56\"16.444287\"W</td></tr><tr><td colspan=\"9\">ÁREA=530,000.00M2 PERIMETRO=3,310.78M</td></tr></tbody></table>\n<p>CROQUIS DE UBICACIÓN-POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR HUAMANTLA, TLAXCALA</p>\n<p><a href=\"https://dof.gob.mx/abrirPDF.php?anio=2025&amp;archivo=14082025-MAT.pdf&amp;repo=#page=62\">Croquis de ubicación en el PDF oficial · página 62</a></p>","tipo_articulo":"ordinario","orden":3,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"b32942df-6636-5c76-ba40-9fa93787b45b","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero","contenido":"<p>ARTÍCULO TERCERO. La superficie a que se refiere el artículo anterior cumple con los criterios de selección</p>\n<p>establecidos en el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, publicado en el Diario Oficial de la Federación el 22 de mayo de 2025, como a continuación se señalan:</p>","tipo_articulo":"ordinario","orden":4,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"186f6911-e7c7-5a38-b390-763962d1bfcc","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · I. Criterio de Macro Localización","contenido":"<p>I. Criterio de Macro Localización</p>\n<p>El inmueble del Polo de Desarrollo Económico para el Bienestar Huamantla Tlaxcala, se localiza en el oriente del estado de Tlaxcala, a pocos kilómetros de los límites con Puebla y de la autopista Puebla-Perote, lo que destaca una ubicación estratégica de la propiedad debido a su excelente conectividad carretera, misma que conecta a la carretera federal 136, con salidas hacia estado de México, Hidalgo (Altiplano), Puebla y Veracruz (Golfo de México). Además, su conexión con Apizaco, Tlaxcala y Teziutlán, lo convierte en un punto de intersección entre zonas agrícolas y urbanas. Esta posición geográfica favorece la diversificación económica, con potencial en agroindustria, turismo cultural y servicios de soporte para la industria.</p>","tipo_articulo":"ordinario","orden":5,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"79d8a8e3-1959-5b17-8fa0-122fcfb1bd8e","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · II. Criterio de Comunicación y Conectividad","contenido":"<p>II. Criterio de Comunicación y Conectividad</p>\n<p>El inmueble del Polo de Desarrollo Económico para el Bienestar Huamantla, Tlaxcala se beneficia de su cercanía a las autopistas Puebla-Perote y Arco-Norte, que permiten la movilidad regional hacia el centro y oriente del país.</p>\n<p>La infraestructura carretera facilita el traslado de bienes agroindustriales y manufacturados, mientras que la red local de caminos rurales conecta eficientemente con comunidades productoras.</p>","tipo_articulo":"ordinario","orden":6,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"481770cb-6b67-5f78-96d7-ba6dd7129b77","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · III. Criterio Poblacional","contenido":"<p>III. Criterio Poblacional</p>\n<p>El Polo de Desarrollo Económico para el Bienestar Huamantla, Tlaxcala se ubica en el municipio de Huamantla, en el estado de Tlaxcala, cuyos municipios colindantes son: al norte con Atltzayanca y Terrenate, al este con Xaloztoc y Tocatlán, al sur con Ixtenco y al oeste con Cuapiaxtla y El Carmen Tequexquitla. Esta ubicación lo conecta con dinámicas regionales tanto de Tlaxcala como del oriente de Puebla.</p>\n<p>También cuenta con cercanía con Ciudad Modelo en Puebla y el nodo automotriz de San José Chiapa y Nopalucan, lo cual le brinda ventajas para integrarse a cadenas productivas industriales y logísticas.</p>\n<p>Conforme al Censo de Población y vivienda 2020, la población total de los municipios mencionados en los párrafos anteriores es mayor a 50,000 habitantes.</p>\n<table><thead><tr><th>Municipio Sede y Municipios Aledaños</th><th>Población Censo 2020</th><th>Población Total Municipio Sede y Municipios Aledaños</th></tr></thead><tbody><tr><td>Nopalucan</td><td>32, 772</td><td rowspan=\"12\">264, 842</td></tr><tr><td>San José Chiapa</td><td>10, 443</td></tr><tr><td>Atlzayanca</td><td>18, 111</td></tr><tr><td>Cuapiaxtla</td><td>16, 222</td></tr><tr><td>Huamantla</td><td>98, 764</td></tr><tr><td>Ixtenco</td><td>7, 504</td></tr><tr><td>Terrenate</td><td>15, 475</td></tr><tr><td>Tocotlán</td><td>6, 294</td></tr><tr><td>Ziltlaltepec de Trinidad Sánchez Santos</td><td>9, 207</td></tr><tr><td>Tzompantepec</td><td>18, 006</td></tr><tr><td>Xaloztoc</td><td>25, 607</td></tr><tr><td>San José Teacalco</td><td>6, 437</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":7,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"ee7bb4a5-1490-5c21-909f-690a2512f98d","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · IV. Criterio de Factibilidad Social","contenido":"<p>IV. Criterio de Factibilidad Social</p>\n<p>El Instituto Nacional de los Pueblos Indígenas mediante oficio CGDI/2025/OF/569, de fecha 5 de junio de 2025, informó lo siguiente:</p>\n<p>\"\"[...]se determinó que no era procedente llevar a cabo el proceso de consulta indígena. [...]\"\"</p>","tipo_articulo":"ordinario","orden":8,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"5112c4a2-ba01-5b59-9d60-d1e099399d73","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · V. Criterio Educativo","contenido":"<p>V. Criterio Educativo</p>\n<p>En las inmediaciones del Polo de Desarrollo Económico para el Bienestar Huamantla, Tlaxcala y los municipios aledaños a este, se localizan las siguientes instituciones de educación media superior y superior:</p>\n<table><thead><tr><th>Municipio</th><th>Institución de Educación Superior</th></tr></thead><tbody><tr><td>Huamantla</td><td>Universidad Tecnológica de Tlaxcala (UTT)</td></tr><tr><td>Huamantla</td><td>Universidad Autónoma de Tlaxcala - Unidad Huamantla</td></tr></tbody></table>\n<table><thead><tr><th>Municipio</th><th>Institución de Educación Media Superior</th></tr></thead><tbody><tr><td>El Carmen Tequexquitla</td><td>Colegio de Estudios Científicos y Tecnológicos de Tlaxcala (CECyTE) No. 01 - Plantel Tequexquitla</td></tr><tr><td>Huamantla</td><td>Centro de Bachillerato Tecnológico Industrial y de Servicios (CBTis) No. 61</td></tr><tr><td>Huamantla</td><td>Colegio de Estudios Científicos y Tecnológicos de Tlaxcala (CECyTE) - Plantel Huamantla</td></tr><tr><td>Ixtenco</td><td>Centro de Bachillerato Tecnológico Agropecuario (CBTA) - Extensión Ixtenco No. 134</td></tr><tr><td>Nopalucan</td><td>Colegio de Estudios Científicos y Tecnológicos de Tlaxcala (CECyTE) No. 18 - Plantel Nopalucan</td></tr><tr><td>Terrenate</td><td>Colegio de Estudios Científicos y Tecnológicos de Tlaxcala (CECyTE) No. 03 - Plantel Terrenate</td></tr><tr><td>Tocatlán</td><td>Colegio de Estudios Científicos y Tecnológicos de Tlaxcala (CECyTE) No. 29 - Plantel Tocatlán</td></tr><tr><td>Zitlaltepec</td><td>Colegio de Estudios Científicos y Tecnológicos de Tlaxcala (CECyTE) - No. 32 Plantel Zitlaltepec</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":9,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"2d94240b-f3ed-5169-b583-9b4bd02059a1","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · VI. Criterio Territorial","contenido":"<p>VI. Criterio Territorial</p>\n<p>Para el desarrollo de las actividades productivas en el Polo de Desarrollo Económico para el Bienestar Huamantla, Tlaxcala son vocaciones productivas, prioritarias y potenciales las siguientes:</p>\n<p>1. Industria textil;</p>\n<p>2. Industrias metálicas básicas;</p>\n<p>3. Fabricación de productos metálicos;</p>\n<p>4. Fabricación de maquinaria y equipo;</p>\n<p>5. Fabricación de equipo de computación;</p>\n<p>6. Aparatos eléctricos;</p>\n<p>7. Fabricación de equipo de transporte, y</p>\n<p>8. Industria de las bebidas y el tabaco</p>","tipo_articulo":"ordinario","orden":10,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"962b7329-bc5d-588f-b354-c2ec0c3f54de","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · VII. Criterio de Factibilidad Industrial","contenido":"<p>VII. Criterio de Factibilidad Industrial</p>\n<p>De acuerdo con el Programa Municipal de Desarrollo Urbano expedido por el Ayuntamiento de Huamantla publicado en el periódico oficial número 39, tercera sección el 24 de septiembre de 2014, se hace constar que el polígono se identifica con uso de suelo industrial.</p>","tipo_articulo":"ordinario","orden":11,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"3af4627d-ceb5-5b50-80f1-20f2709307de","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · VIII. Criterio de Sostenibilidad","contenido":"<p>VIII. Criterio de Sostenibilidad</p>\n<p>La Secretaría de Medio Ambiente y Recursos Naturales, mediante oficio número SDSEC/800/79/2025 de fecha 3 de junio de 2025, determinó que el Polo de Desarrollo Económico para el Bienestar Huamantla, Tlaxcala es viable en materia ambiental, sujeto al cumplimiento de los requisitos normativos aplicables y a la integración de medidas específicas para protección ecológica y gestión hídrica.</p>","tipo_articulo":"ordinario","orden":12,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"55639c15-bc98-592d-a452-75f78a56dedc","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · IX. Criterio de Servicios e Infraestructura","contenido":"<p>IX. Criterio de Servicios e Infraestructura</p>\n<p>El polígono cuenta con los servicios e infraestructura básicos para el desarrollo de las actividades productivas. Dispone de vialidades, energía eléctrica, agua potable, drenaje y conectividad, lo que garantiza condiciones adecuadas para la operación de empresas e industrias, y contribuye al impulso del desarrollo regional y la atracción de inversiones.</p>","tipo_articulo":"ordinario","orden":13,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"45533d85-6c13-558a-8538-385719e5ea1a","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo tercero · X. Criterio de Propiedad","contenido":"<p>X. Criterio de Propiedad</p>\n<p>De conformidad con la información proporcionada por la entidad federativa y la documentación que fue puesta a disposición del Comité Intersecretarial de Promoción, se desprende que los predios que conforman el área destinada al Polo de Desarrollo Económico para el Bienestar Huamantla, Tlaxcala son propiedad del Gobierno del estado de Tlaxcala.</p>","tipo_articulo":"ordinario","orden":14,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"e7c88a7d-f900-5c51-878e-2b317c6d1100","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Artículo cuarto","contenido":"<p>Artículo cuarto. El estado de Tlaxcala y la Secretaría de Economía deberán suscribir el convenio de coordinación a que se refiere el artículo Décimo, párrafo tercero del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.</p>","tipo_articulo":"ordinario","orden":15,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"ba7280cd-badd-593c-9ec4-a870b60569b4","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Transitorio único","contenido":"<p>TRANSITORIO</p>\n<p>ÚNICO. La presente Declaratoria entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.</p>","tipo_articulo":"transitorio","orden":16,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"01a7f7ef-7501-58a8-aeaa-91043d98df54","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Firma del acuerdo","contenido":"<p>Ciudad de México, a 11 de agosto de 2025.- El Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.</p>","tipo_articulo":"complementario","orden":17,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"aa902552-f70d-5beb-9a78-729ba4ac8653","ley_id":"068f6c91-aa4a-51bd-a4c0-4e11c33bd9a0","identificador":"Notas al pie","contenido":"<p>1 https://www.gob.mx/cms/uploads/attachment/file/981072/PND_2025-2030_v250226_14.pdf</p>","tipo_articulo":"nota","orden":18,"titulo_nombre":"Huamantla","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
END
$carga$;
